// function processAge(age)
// String hai to parseFloat karo
// Number nahi hai: "Invalid age"
// < 0: "Age cannot be negative"
// > 150: "Age too high"
// Warna number return karo

solution:
function processAge(age) {
  if (typeof age === "string") age = parseFloat(age)
  if (typeof age !== "number" || Number.isNaN(age)) return "Invalid age"
  if (age < 0) return "Age cannot be negative"
  if (age > 150) return "Age too high"
  return age
}
